export const isWordChar = (c: string): boolean => /[a-zA-Z]/.test(c);
===== rules-builder/parse-char.ts =====
import { GrammarParseError } from '../utils/errors';

const ESCAPE_CHARS: Record<string, number> = {
  t: 9,
  r: 13,
  n: 10,
};

const LITERAL_ESCAPES = ['"', '[', ']', '\\'];

export const parseChar = (src: string, pos: number): [number, number] => {
  if (pos >= src.length) {
    throw new GrammarParseError(
      src,
      pos,
      'Unexpected end of grammar input, failed to complete parse',
    );
  }

  if (src[pos] === '\\') {
    const next = src[pos + 1];
    if (next === 'x') {
      return [parseInt(src.slice(pos + 2, pos + 4), 16), 4];
    }
    if (next === 'u') {
      return [parseInt(src.slice(pos + 2, pos + 6), 16), 6];
    }
    if (next === 'U') {
      return [parseInt(src.slice(pos + 2, pos + 10), 16), 10];
    }
    if (next in ESCAPE_CHARS) {
      return [ESCAPE_CHARS[next], 2];
    }
    if (LITERAL_ESCAPES.includes(next)) {
      return [next.charCodeAt(0), 2];
    }
    throw new GrammarParseError(src, pos, `Unknown escape at ${src[pos]}`);
  }

  return [src.charCodeAt(pos), 1];
};
===== rules-builder/parse-name.ts =====
import { GrammarParseError } from '../utils/errors';
import { isWordChar } from './is-word-char';

export const PARSE_NAME_ERROR = 'Failed to find a valid name';

export const VALID_NAME_SEPARATORS = ['-', '_'];

export const parseName = (grammar: string, pos: number): string => {
  let name = '';
  while (
    pos < grammar.length &&
    (isWordChar(grammar[pos]) || VALID_NAME_SEPARATORS.includes(grammar[pos]))
  ) {
    name += grammar[pos];
    pos += 1;
  }
  if (!name) {
    throw new GrammarParseError(grammar, pos, PARSE_NAME_ERROR);
  }
  return name;
};
===== rules-builder/parse-space.ts =====
export const parseSpace = (
  src: string,
  pos: number,
  newlineOk: boolean,
): number => {
  while (
    pos < src.length &&
    (src[pos] === ' ' ||
      src[pos] === '\t' ||
      src[pos] === '#' ||
      (newlineOk && (src[pos] === '\r' || src[pos] === '\n')))
  ) {
    if (src[pos] === '#') {
      while (pos < src.length && src[pos] !== '\r' && src[pos] !== '\n') {
        pos += 1;
      }
    } else {
      pos += 1;
    }
  }
  return pos;
};
===== rules-builder/rules-builder-types.ts =====
export enum InternalRuleType {
  CHAR = 'char',
  CHAR_ALT = 'char_alt',
  ALT = 'alt',
  CHAR_NOT = 'char_not',
  CHAR_RNG_UPPER = 'char_rng_upper',
  REF = 'ref',
  END = 'end',
}

export abstract class InternalBase {
  abstract readonly type: InternalRuleType;
}

export abstract class InternalBaseWithInt extends InternalBase {
  value: number;

  constructor(value: number) {
    super();
    this.value = value;
  }
}

export abstract class InternalBaseWithListOfInts extends InternalBase {
  value: number[];

  constructor(value: number[]) {
    super();
    // the incoming list is copied so later mutations of the source do not leak in.
    this.value = value.slice();
  }
}

export class InternalRuleDefChar extends InternalBaseWithListOfInts {
  readonly type = InternalRuleType.CHAR;
}

export class InternalRuleDefCharNot extends InternalBaseWithListOfInts {
  readonly type = InternalRuleType.CHAR_NOT;
}

export class InternalRuleDefCharAlt extends InternalBaseWithInt {
  readonly type = InternalRuleType.CHAR_ALT;
}

export class InternalRuleDefCharRngUpper extends InternalBaseWithInt {
  readonly type = InternalRuleType.CHAR_RNG_UPPER;
}

export class InternalRuleDefReference extends InternalBaseWithInt {
  readonly type = InternalRuleType.REF;
}

export class InternalRuleDefAlt extends InternalBase {
  readonly type = InternalRuleType.ALT;
}

export class InternalRuleDefEnd extends InternalBase {
  readonly type = InternalRuleType.END;
}

export type InternalRuleDef =
  | InternalRuleDefChar
  | InternalRuleDefCharNot
  | InternalRuleDefCharAlt
  | InternalRuleDefCharRngUpper
  | InternalRuleDefReference
  | InternalRuleDefAlt
  | InternalRuleDefEnd;

export type InternalRuleDefCharOrAltChar =
  | InternalRuleDefChar
  | InternalRuleDefCharAlt;

export const isRuleDefAlt = (
  rule?: InternalRuleDef,
): rule is InternalRuleDefAlt => rule instanceof InternalRuleDefAlt;

export const isRuleDefRef = (
  rule?: InternalRuleDef,
): rule is InternalRuleDefReference => rule instanceof InternalRuleDefReference;

export const isRuleDefEnd = (
  rule?: InternalRuleDef,
): rule is InternalRuleDefEnd => rule instanceof InternalRuleDefEnd;

export const isRuleDefChar = (
  rule?: InternalRuleDef,
): rule is InternalRuleDefChar => rule instanceof InternalRuleDefChar;

export const isRuleDefCharNot = (
  rule?: InternalRuleDef,
): rule is InternalRuleDefCharNot => rule instanceof InternalRuleDefCharNot;

export const isRuleDefCharAlt = (
  rule?: InternalRuleDef,
): rule is InternalRuleDefCharAlt => rule instanceof InternalRuleDefCharAlt;

export const isRuleDefCharRngUpper = (
  rule?: InternalRuleDef,
): rule is InternalRuleDefCharRngUpper =>
  rule instanceof InternalRuleDefCharRngUpper;
===== rules-builder/rules-builder.ts =====
import { GrammarParseError } from '../utils/errors';
import { isWordChar } from './is-word-char';
import { parseChar } from './parse-char';
import { parseName } from './parse-name';
import { parseSpace } from './parse-space';
import {
  InternalRuleDefAlt,
  InternalRuleDefChar,
  InternalRuleDefCharAlt,
  InternalRuleDefCharNot,
  InternalRuleDefCharRngUpper,
  InternalRuleDefEnd,
  InternalRuleDefReference,
  InternalRuleType,
  isRuleDefRef,
  type InternalRuleDef,
} from './rules-builder-types';
import { SymbolIds } from './symbol-ids';

export const getOutElements = (
  typeOfRule: InternalRuleType,
  startcharValue: number,
): InternalRuleDef => {
  switch (typeOfRule) {
    case InternalRuleType.CHAR:
      return new InternalRuleDefChar([startcharValue]);
    case InternalRuleType.CHAR_NOT:
      return new InternalRuleDefCharNot([startcharValue]);
    case InternalRuleType.CHAR_RNG_UPPER:
      return new InternalRuleDefCharRngUpper(startcharValue);
    case InternalRuleType.ALT:
      return new InternalRuleDefAlt();
    case InternalRuleType.END:
      return new InternalRuleDefEnd();
    case InternalRuleType.CHAR_ALT:
      return new InternalRuleDefCharAlt(startcharValue);
    default:
      throw new Error(`Invalid type: ${typeOfRule}`);
  }
};

export class RulesBuilder {
  pos = 0;
  symbolIds = new SymbolIds();
  rules: InternalRuleDef[][] = [];
  src: string;
  start: number;
  timeLimit: number;

  constructor(src: string, limit = 1000) {
    this.src = src;
    this.start = performance.now();
    this.timeLimit = limit;
    this.parse(src);
  }

  parse(src: string): void {
    this.pos = parseSpace(src, 0, true);
    while (this.pos < src.length) {
      this.parseRule(src);
    }

    // Validate the state to ensure that all rules are defined
    for (const rule of this.rules) {
      for (const elem of rule) {
        if (isRuleDefRef(elem)) {
          const ruleExists =
            elem.value < this.rules.length && this.rules[elem.value].length > 0;
          if (!ruleExists) {
            const missingRuleName = this.symbolIds.reverseGet(elem.value);
            let missingRulePos = this.symbolIds.getPos(missingRuleName);

            // Skip over the ::= and any whitespace
            while (
              missingRulePos < src.length &&
              (src[missingRulePos] === ':' ||
                src[missingRulePos] === '=' ||
                /\s/.test(src[missingRulePos]))
            ) {
              missingRulePos += 1;
            }

            throw new GrammarParseError(
              src,
              missingRulePos,
              `Undefined rule identifier "${missingRuleName}"`,
            );
          }
        }
      }
    }
  }

  parseRule(src: string): void {
    const name = parseName(src, this.pos);
    this.pos = parseSpace(src, this.pos + name.length, false);
    const ruleId = this.getSymbolId(name, name.length);

    this.pos = parseSpace(src, this.pos, true);
    if (
      !(
        this.pos + 2 < src.length && // Ensure the position + 2 is within bounds
        src[this.pos] === ':' &&
        src[this.pos + 1] === ':' &&
        src[this.pos + 2] === '='
      )
    ) {
      throw new GrammarParseError(src, this.pos, `Expecting ::= at ${this.pos}`);
    }
    this.pos += 3;
    this.pos = parseSpace(src, this.pos, true);

    this.parseAlternates(name, ruleId);

    // Check if this.pos is within the bounds of src before checking for a carriage return
    if (this.pos < src.length && src[this.pos] === '\r') {
      this.pos += src[this.pos + 1] === '\n' ? 2 : 1;
    } else if (this.pos < src.length && src[this.pos] === '\n') {
      this.pos += 1;
    } else if (this.pos < src.length && src[this.pos]) {
      throw new GrammarParseError(
        src,
        this.pos,
        `Expecting newline or end at ${this.pos}`,
      );
    }
    this.pos = parseSpace(src, this.pos, true);
  }

  getSymbolId(src: string, length: number): number {
    const nextId = this.symbolIds.size;
    const key = src.slice(0, length);
    if (!this.symbolIds.has(key)) {
      this.symbolIds.set(key, nextId, this.pos);
    }
    return this.symbolIds.get(key) as number;
  }

  generateSymbolId(baseName: string): number {
    const nextId = this.symbolIds.size;
    this.symbolIds.set(`${baseName}_${nextId}`, nextId, this.pos);
    return nextId;
  }

  addRule(ruleId: number, rule: InternalRuleDef[]): void {
    while (this.rules.length <= ruleId) {
      this.rules.push([]);
    }
    this.rules[ruleId] = rule;
  }

  checkDuration(): void {
    if ((performance.now() - this.start) / 1000 > this.timeLimit) {
      throw new GrammarParseError(
        this.src,
        this.pos,
        `Duration of ${this.timeLimit} exceeded`,
      );
    }
  }

  parseSequence(
    ruleName: string,
    outElements: InternalRuleDef[],
    depth = 0,
  ): void {
    const isNested = depth !== 0;
    const src = this.src;
    let lastSymStart = outElements.length;

    while (this.pos < src.length) {
      if (src[this.pos] === '"') {
        this.pos += 1;
        lastSymStart = outElements.length;
        while (src[this.pos] !== '"') {
          this.checkDuration();
          const [value, incPos] = parseChar(src, this.pos);
          outElements.push(new InternalRuleDefChar([value]));
          this.pos += incPos;
        }
        this.pos = parseSpace(src, this.pos + 1, isNested);
      } else if (src[this.pos] === '[') {
        this.pos += 1;
        let startType = InternalRuleType.CHAR;
        if (src[this.pos] === '^') {
          this.pos += 1;
          startType = InternalRuleType.CHAR_NOT;
        }
        lastSymStart = outElements.length;
        while (src[this.pos] !== ']') {
          this.checkDuration();
          const type =
            lastSymStart < outElements.length
              ? InternalRuleType.CHAR_ALT
              : startType;
          const [startcharValue, incPos] = parseChar(src, this.pos);
          this.pos += incPos;
          outElements.push(getOutElements(type, startcharValue));

          if (src[this.pos] === '-' && src[this.pos + 1] !== ']') {
            this.pos += 1;
            const [endcharValue, endIncPos] = parseChar(src, this.pos);
            outElements.push(new InternalRuleDefCharRngUpper(endcharValue));
            this.pos += endIncPos;
          }
        }
        this.pos = parseSpace(src, this.pos + 1, isNested);
      } else if (isWordChar(src[this.pos])) {
        const name = parseName(src, this.pos);
        const refRuleId = this.getSymbolId(name, name.length);
        this.pos += name.length;
        this.pos = parseSpace(src, this.pos, isNested);

        lastSymStart = outElements.length;
        outElements.push(new InternalRuleDefReference(refRuleId));
      } else if (src[this.pos] === '(') {
        this.pos = parseSpace(src, this.pos + 1, true);
        const subRuleId = this.generateSymbolId(ruleName);
        this.parseAlternates(ruleName, subRuleId, depth + 1);
        lastSymStart = outElements.length;
        outElements.push(new InternalRuleDefReference(subRuleId));
        if (src[this.pos] !== ')') {
          throw new GrammarParseError(
            src,
            this.pos,
            `Expecting ')' at ${this.pos}`,
          );
        }
        this.pos = parseSpace(src, this.pos + 1, isNested);
      } else if ('*+?'.includes(src[this.pos])) {
        if (lastSymStart === outElements.length) {
          throw new GrammarParseError(
            src,
            this.pos,
            `Expecting preceding item to */+/? at ${this.pos}`,
          );
        }
        const subRuleId = this.generateSymbolId(ruleName);
        const subRule = outElements.slice(lastSymStart);
        if ('*+'.includes(src[this.pos])) {
          subRule.push(new InternalRuleDefReference(subRuleId));
        }
        subRule.push(new InternalRuleDefAlt());
        if (src[this.pos] === '+') {
          subRule.push(...outElements.slice(lastSymStart));
        }
        subRule.push(new InternalRuleDefEnd());
        this.addRule(subRuleId, subRule);
        outElements.splice(
          lastSymStart,
          outElements.length - lastSymStart,
          new InternalRuleDefReference(subRuleId),
        );
        this.pos = parseSpace(src, this.pos + 1, isNested);
      } else {
        break;
      }
    }
  }

  parseAlternates(ruleName: string, ruleId: number, depth = 0): void {
    const src = this.src;
    const rule: InternalRuleDef[] = [];
    this.parseSequence(ruleName, rule, depth);
    // Ensure that this.pos is within bounds before checking src[this.pos]
    while (this.pos < src.length && src[this.pos] === '|') {
      this.checkDuration();
      rule.push(new InternalRuleDefAlt());
      this.pos = parseSpace(src, this.pos + 1, true);
      this.parseSequence(ruleName, rule, depth);
    }
    rule.push(new InternalRuleDefEnd());
    this.addRule(ruleId, rule);
  }
}
